@using sv_15db34aa130245cc87b2b6cbbf719b4c.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    SelectedChannelId="_selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_threadOpen ? "with-thread" : "full-width")">
        @if (_currentChannel is not null)
        {
            <MessageArea Channel="_currentChannel"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         HasMoreMessages="_hasMoreMessages"
                         OnLoadMore="LoadOlderMessages"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction" />
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     ThreadMessages="_threadMessages"
                     OnReply="SendThreadReply"
                     OnClose="CloseThread" />
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = new();
    private int _selectedChannelId;
    private Channel? _currentChannel;
    private List<Message> _messages = new();
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private bool _hasMoreMessages = true;

    private bool _threadOpen;
    private int _threadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _currentChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = new();
        _threadSummaries = new();
        _hasMoreMessages = true;
        CloseThread();

        var messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count >= PageSize;
        await BuildThreadSummaries();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessages()
    {
        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        _hasMoreMessages = older.Count >= PageSize;
        // Prepend older messages
        _messages.InsertRange(0, older);
        await BuildThreadSummaries();
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = new();
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootId);
        _threadMessages.Add(reply);
        await BuildThreadSummaries();
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect updated reactions
        var refreshed = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _messages.Count);
        _messages = refreshed;
    }

    private async Task BuildThreadSummaries()
    {
        _threadSummaries = new();
        // Identify messages that have replies (by checking if any message has a ReplyToId pointing to them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is not null)
            .Select(m => m.ReplyToId!.Value)
            .Distinct();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                _threadSummaries[rootId] = new ThreadSummary(
                    rootId,
                    thread.Count,
                    thread.Max(t => t.SentAt));
            }
        }

        // Also check for root messages that are thread starters via GetThread
        foreach (var msg in _messages.Where(m => m.ReplyToId is null))
        {
            if (!_threadSummaries.ContainsKey(msg.Id))
            {
                var thread = await ChatService.GetThreadAsync(msg.Id);
                if (thread.Count > 0)
                {
                    _threadSummaries[msg.Id] = new ThreadSummary(
                        msg.Id,
                        thread.Count,
                        thread.Max(t => t.SentAt));
                }
            }
        }
    }
}

