}

/* ===== Channel Sidebar ===== */
::deep .channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #2b2d42;
    color: #edf2f4;
    display: flex;
    flex-direction: column;
    overflow-y: auto;
}

::deep .sidebar-title {
    padding: 1rem;
    margin: 0;
    font-size: 0.9rem;
